insert into public.analysis_types
  (slug, name, aliases, summary, intro, command, tutorial_slug, requires_structure, field_schema, file_rules, sort_order)
values
  ('rmsd', 'RMSD analysis', array['RMSD', 'Protein RMSD', 'Backbone RMSD', 'Ligand RMSD', 'Root mean square deviation']::text[], 'How far the protein backbone and ligand drift from the starting structure over time.', array['Root-mean-square deviation (RMSD) is the average distance between the atoms of a structure and a reference, usually the starting frame, after the two are superimposed by least-squares fitting. In an MD simulation it is the first plot most people look at, because it shows whether the system has reached a stable state.', 'A backbone RMSD curve that rises quickly and then levels off means the protein has settled; one that keeps climbing suggests the structure is still relaxing, or unfolding. For a ligand, RMSD is calculated after fitting on the protein, so a ligand curve that jumps or drifts steadily points to the ligand moving within, or leaving, the binding pocket.', 'RMSD says how much a structure changed, not where. Read it together with RMSF (which residues move) and the radius of gyration (whether the fold stays compact), and always report which atoms were used for the fit and for the calculation.']::text[], 'gmx rms -s md.tpr -f md_fit.xtc -o rmsd.xvg', 'rmsd-rmsf-analysis-gromacs', true, '{"citation":"optional","molecules":"required"}'::jsonb, '{"allowed":["xvg","csv","txt","dat","png","svg","pdf","pdb","gro"],"required":["xvg"],"max_mb":50}'::jsonb, 10),
  ('rmsf', 'RMSF analysis', array['RMSF', 'Protein RMSF', 'Root mean square fluctuation', 'Residue fluctuation']::text[], 'Per-residue flexibility of the protein around its average position.', array['Root-mean-square fluctuation (RMSF) measures how much each residue moves around its own average position during the simulation. Where RMSD summarises the whole structure in one number per frame, RMSF gives one number per residue, so it shows which parts of the protein are rigid and which are flexible.', 'Peaks usually correspond to loops and the chain termini, while low values mark secondary-structure elements and buried regions. Comparing RMSF between an apo protein and its ligand-bound complex is a common way to see whether binding stiffens the pocket or a nearby loop.', 'RMSF is computed on a trajectory that has already been fitted to a reference, and the results depend on the time window used, so state the range of frames in the methods.']::text[], 'gmx rmsf -s md.tpr -f md_fit.xtc -o rmsf.xvg -res', 'rmsd-rmsf-analysis-gromacs', true, '{"citation":"optional","molecules":"required"}'::jsonb, '{"allowed":["xvg","csv","txt","dat","png","svg","pdf","pdb","gro"],"required":["xvg"],"max_mb":50}'::jsonb, 20),
  ('radius-of-gyration', 'Radius of gyration (Rg)', array['Rg', 'Radius of gyration', 'Protein compactness', 'Compactness']::text[], 'How compact the protein stays over the simulation.', array['The radius of gyration (Rg) is the mass-weighted root-mean-square distance of a molecule''s atoms from its centre of mass. It is a simple measure of compactness: a tightly folded protein has a small, steady Rg, and unfolding or opening of domains shows up as a rise.', 'Because it is a single number per frame, Rg is easy to compare between simulations, for example a protein with and without a bound ligand. A flat line means the fold is maintained; a step change often marks a conformational transition worth a closer look at the structures.']::text[], 'gmx gyrate -s md.tpr -f md_fit.xtc -o gyrate.xvg', 'rmsd-rmsf-analysis-gromacs', true, '{"citation":"optional","molecules":"required"}'::jsonb, '{"allowed":["xvg","csv","txt","dat","png","svg","pdf","pdb","gro"],"required":["xvg"],"max_mb":50}'::jsonb, 30),
  ('sasa', 'Solvent-accessible surface area (SASA)', array['SASA', 'Solvent accessible surface area', 'Surface area', 'Protein SASA']::text[], 'How much of the protein surface is exposed to solvent.', array['Solvent-accessible surface area (SASA) is the area of the molecule that a probe sphere the size of a water molecule can touch. It reports how exposed the protein is to solvent and is often used alongside Rg to judge compaction and burial of hydrophobic groups.', 'A falling SASA can mean the protein is collapsing or a pocket is closing around a ligand; a rising SASA can mean domains opening. SASA can be calculated for the whole protein, per residue, or for the binding site only.']::text[], 'gmx sasa -s md.tpr -f md_fit.xtc -o sasa.xvg -or resarea.xvg', null, true, '{"citation":"optional","molecules":"required"}'::jsonb, '{"allowed":["xvg","csv","txt","dat","png","svg","pdf","pdb","gro"],"required":["xvg"],"max_mb":50}'::jsonb, 40),
  ('hydrogen-bonds', 'Hydrogen-bond analysis', array['H-bond', 'H-bonds', 'Hydrogen bonds', 'Hydrogen bond analysis', 'Hbond']::text[], 'Hydrogen bonds between the protein and ligand, or within the protein, per frame.', array['Hydrogen-bond analysis counts the hydrogen bonds between two groups in every frame, most often protein and ligand. Persistent bonds anchor a ligand in its pocket, while bonds that form and break repeatedly show a more dynamic interaction.', 'A hydrogen bond is defined geometrically. GROMACS defaults to a donor–acceptor distance of at most 0.35 nm and a hydrogen–donor–acceptor angle of at most 30 degrees; report these cut-offs if you change them. Beyond the count over time, the occupancy of each individual bond (the fraction of frames it is present) identifies the residues that matter most.']::text[], 'gmx hbond -s md.tpr -f md_fit.xtc -n index.ndx -num hbnum.xvg', null, true, '{"citation":"optional","molecules":"required"}'::jsonb, '{"allowed":["xvg","csv","txt","dat","xpm","png","svg","pdf","pdb","gro"],"required":["xvg"],"max_mb":50}'::jsonb, 50),
  ('contact-map', 'Protein–ligand contact analysis', array['Contact map', 'Contacts', 'Residue contacts', 'Protein ligand contacts']::text[], 'Which residues stay in contact with the ligand, and for how long.', array['Contact analysis records, for every frame, which protein residues lie within a chosen distance of the ligand, commonly 0.4 nm. Plotted as residue against time, long unbroken rows are the residues that hold the ligand in place.', 'Contacts complement hydrogen bonds because they also capture hydrophobic and van der Waals interactions, which hydrogen-bond counts miss entirely.']::text[], 'gmx mindist -s md.tpr -f md_fit.xtc -n index.ndx -od mindist.xvg -on numcont.xvg -d 0.4', null, true, '{"citation":"optional","molecules":"required"}'::jsonb, '{"allowed":["xvg","csv","txt","dat","xpm","png","svg","pdf","pdb","gro"],"required":[],"max_mb":50}'::jsonb, 60),
  ('mm-pbsa', 'MM-PBSA binding free energy', array['MMPBSA', 'MM/PBSA', 'MM-GBSA', 'Binding free energy', 'Binding energy']::text[], 'Estimated protein–ligand binding free energy and its components.', array['MM-PBSA (molecular mechanics Poisson–Boltzmann surface area) estimates the binding free energy of a ligand from snapshots of an MD trajectory. The result is split into van der Waals, electrostatic, polar solvation and non-polar solvation terms, so you can see what drives binding.', 'More negative values indicate stronger predicted binding. The method is best used to rank related ligands rather than to predict absolute affinities, and entropy is often left out; report the frames used, the dielectric constants and whether entropy was included. Common tools are gmx_MMPBSA and g_mmpbsa.']::text[], 'gmx_MMPBSA -O -i mmpbsa.in -cs md.tpr -ci index.ndx -cg 1 13 -ct md_fit.xtc', null, true, '{"citation":"optional","molecules":"required"}'::jsonb, '{"allowed":["csv","dat","txt","xvg","itp","png","svg","pdf","pdb","gro"],"required":[],"max_mb":50}'::jsonb, 70),
  ('pca', 'Principal component analysis (PCA)', array['PCA', 'Essential dynamics', 'Principal components']::text[], 'The dominant collective motions of the protein.', array['Principal component analysis diagonalises the covariance matrix of atomic positions to find the collective motions that account for most of the movement in a trajectory. The first few components usually describe large, functionally relevant motions such as domain closing.', 'Projecting the trajectory onto the first two components (PC1 and PC2) gives a map of the conformations the protein visits; separate clusters are distinct states. The same projection is the input for the free-energy landscape.']::text[], 'gmx covar -s md.tpr -f md_fit.xtc -o eigenval.xvg -v eigenvec.trr && gmx anaeig -s md.tpr -f md_fit.xtc -v eigenvec.trr -first 1 -last 2 -2d 2dproj.xvg', null, true, '{"citation":"optional","molecules":"required"}'::jsonb, '{"allowed":["xvg","xpm","csv","dat","txt","png","svg","pdf","pdb","gro"],"required":[],"max_mb":100}'::jsonb, 80),
  ('free-energy-landscape', 'Free-energy landscape (FEL)', array['FEL', 'Free energy landscape', 'Gibbs free energy landscape', 'Energy landscape']::text[], 'Gibbs free energy over the main conformational coordinates.', array['A free-energy landscape turns how often the simulation visits each conformation into a Gibbs free energy, using the Boltzmann relation. It is usually drawn over PC1 and PC2 from a principal component analysis.', 'Deep basins are stable, highly populated states; the barriers between them show how easily the protein switches conformation. Landscapes are only meaningful when the simulation samples the states often enough, so report the length and the number of replicas.']::text[], 'gmx sham -f 2dproj.xvg -ls gibbs.xpm', null, true, '{"citation":"optional","molecules":"required"}'::jsonb, '{"allowed":["xpm","xvg","csv","dat","txt","png","svg","pdf","pdb","gro"],"required":[],"max_mb":100}'::jsonb, 90),
  ('dccm', 'Dynamic cross-correlation (DCCM)', array['DCCM', 'Cross correlation', 'Dynamic cross correlation matrix', 'Residue correlation']::text[], 'Which residues move together and which move in opposition.', array['The dynamic cross-correlation matrix (DCCM) shows, for every pair of residues, how correlated their motions are, from +1 (move together) to -1 (move in opposite directions). Blocks off the diagonal reveal regions of the protein that are coupled, even when they are far apart in sequence.', 'It is typically calculated on C-alpha atoms with tools such as Bio3D or MD-TASK, and comparing the matrix with and without a ligand shows how binding changes the protein''s internal communication.']::text[], null, null, true, '{"citation":"optional","molecules":"required"}'::jsonb, '{"allowed":["csv","dat","txt","xpm","png","svg","pdf","pdb","gro"],"required":[],"max_mb":50}'::jsonb, 100),
  ('other', 'Other MD analyses', array['Other', 'Other analysis', 'Custom analysis']::text[], 'Other simulation types and analysis methods that don''t fit the standard list.', array['Molecular dynamics covers many methods beyond the standard stability analyses: membrane and lipid properties, nucleic-acid simulations, peptide folding, enhanced sampling and more. Records in this category describe the method in their methodology field and are tagged for discovery.', 'If you think a method deserves its own category, you will be able to request it from your dashboard and the administrators will review it.']::text[], null, null, false, '{"citation":"optional","molecules":"optional"}'::jsonb, '{"allowed":["xvg","csv","txt","dat","xpm","pdb","gro","xtc","trr","tpr","mol2","itp","png","svg","pdf","zip","other"],"required":[],"max_mb":500}'::jsonb, 110)
insert into public.simulation_types (slug, name, aliases, summary, intro, requires_structure, sort_order)
values
  ('apo-protein', 'Apo protein', array['Apo', 'Apo form', 'Unbound protein', 'Ligand-free protein', 'Free protein', 'Protein only']::text[], 'A protein simulated on its own, without a ligand or binding partner.', array['An apo simulation follows a protein in water and ions with nothing bound to it. It is the reference state for most studies: it shows how flexible the protein is on its own, which loops move, and whether the binding pocket is open or closed before any ligand arrives.', 'Apo runs are usually paired with a ligand-bound (holo) simulation of the same protein, set up and run in exactly the same way, so differences in RMSD, RMSF, hydrogen bonds or pocket volume can be attributed to binding. Start from an apo crystal structure when one exists, or remove the ligand from a holo structure and say so in the methods.']::text[], true, 10),
  ('protein-ligand-complex', 'Protein–ligand complex', array['Protein ligand', 'Holo', 'Holo protein', 'Ligand-bound', 'Drug–protein complex', 'Protein small molecule']::text[], 'A protein with a bound small molecule, such as a drug candidate, substrate or cofactor.', array['Protein–ligand simulations place a small molecule in a binding site and follow the complex over time. They are used to test whether a docked pose stays put, which residues and hydrogen bonds hold the ligand, and to estimate binding free energies with methods such as MM-PBSA.', 'The ligand needs its own force-field parameters, for example from CGenFF or GAFF, and the quality of those parameters and of the starting pose largely decides how reliable the result is. Run several replicas, and compare with an apo simulation of the same protein where you can.']::text[], true, 20),
  ('protein-protein-complex', 'Protein–protein complex', array['Protein protein', 'PPI', 'Protein–protein interaction', 'Protein complex', 'Antibody–antigen']::text[], 'Two or more proteins bound to each other, such as a complex or an antibody with its antigen.', array['These simulations study how proteins recognise and hold on to each other: which residues form the interface, how stable it is, and how it changes when a partner is mutated or a small molecule is added.', 'Systems are large and therefore expensive. Contacts, hydrogen bonds, interface area and per-residue energy contributions are the usual analyses. Starting structures often come from docking, so check that the interface is stable before reading anything into it.']::text[], true, 30),
  ('membrane-protein', 'Membrane protein', array['Membrane', 'Transmembrane protein', 'Lipid bilayer', 'Protein in membrane', 'GPCR', 'Ion channel']::text[], 'A protein embedded in a lipid bilayer, such as a receptor, channel or transporter.', array['Membrane protein simulations place the protein in a lipid bilayer, often POPC, with water on both sides. Tools such as CHARMM-GUI Membrane Builder help with orientation and packing.', 'The lipids must equilibrate around the protein, so these runs need a longer, gradually released restraint protocol than soluble proteins. Typical analyses add membrane thickness, area per lipid, lipid order and protein–lipid contacts to the usual RMSD and RMSF.']::text[], true, 40),
  ('protein-dna-rna-complex', 'Protein–DNA/RNA complex', array['Protein DNA', 'Protein RNA', 'Protein–DNA', 'Protein–RNA', 'Nucleoprotein', 'Protein nucleic acid']::text[], 'A protein bound to DNA or RNA.', array['These systems include transcription factors on DNA, polymerases, ribosomal proteins and RNA-binding proteins. The highly charged nucleic acid makes ions and water placement important, so salt concentration and ion parameters need care.', 'Use a force field with well-tested nucleic-acid parameters, for example CHARMM36 or the AMBER OL15 (DNA) and OL3 (RNA) parameters, and watch base pairing and groove geometry along with the protein–nucleic-acid contacts.']::text[], true, 50),
  ('peptide', 'Peptide', array['Peptides', 'Short peptide', 'Peptide folding', 'Peptide–protein']::text[], 'A short chain of amino acids, simulated alone or bound to a protein.', array['Peptides are small and flexible, so they are simulated to study folding, conformational preferences and binding to a protein partner. Because they sample many shapes, convergence is the main challenge.', 'Replica exchange or other enhanced sampling is common, and results are usually reported as ensembles or clusters of conformations rather than a single structure.']::text[], false, 60),
  ('nucleic-acid', 'Nucleic acid', array['DNA', 'RNA', 'DNA simulation', 'RNA simulation', 'Oligonucleotide', 'G-quadruplex']::text[], 'DNA or RNA simulated without a protein partner.', array['Nucleic acid simulations look at helix geometry, flexibility, the folding of RNA motifs and structures such as G-quadruplexes. They are sensitive to the ion environment and to the force field.', 'Common analyses are base-pair and base-step parameters, groove widths, backbone torsions and RMSD against the experimental structure. Report the force field and ion model with the results.']::text[], false, 70),
  ('umbrella-sampling', 'Umbrella sampling', array['Umbrella', 'PMF', 'Potential of mean force', 'Umbrella sampling simulation']::text[], 'Enhanced sampling that builds a free-energy profile along a chosen path using biased windows.', array['Umbrella sampling holds the system at a series of positions along a reaction coordinate, such as the distance between a ligand and its pocket, using a harmonic bias in each window. The biased histograms are then combined, usually with WHAM, into a potential of mean force.', 'Neighbouring windows must overlap, each window needs enough sampling to converge, and the result depends on the chosen coordinate. In GROMACS the pulling code generates the windows and gmx wham combines them. Report the force constant, window spacing and simulation time per window.']::text[], true, 80),
  ('metadynamics', 'Metadynamics', array['Well-tempered metadynamics', 'MetaD', 'WT-MetaD', 'PLUMED metadynamics']::text[], 'Enhanced sampling that fills free-energy wells with a history-dependent bias.', array['Metadynamics adds small Gaussian hills to the potential along chosen collective variables, so regions already visited become less attractive and the system is pushed to explore new ones. The accumulated bias estimates the free-energy surface.', 'It is usually run with PLUMED, often in the well-tempered form where the hill height decreases over time. The quality depends on good collective variables: show that the free-energy estimate converges, and report the hill height, width and deposition rate.']::text[], true, 90),
  ('replica-exchange', 'Replica exchange (REMD)', array['REMD', 'T-REMD', 'Replica exchange MD', 'Parallel tempering', 'Hamiltonian replica exchange', 'H-REMD']::text[], 'Several copies of the system run in parallel at different temperatures or settings and swap.', array['In replica exchange, replicas run at different temperatures (T-REMD) or with modified potentials (Hamiltonian REMD) and periodically attempt to swap. High-temperature replicas cross barriers quickly and pass new conformations down to the replica of interest.', 'Acceptance between neighbouring replicas must be reasonable, which sets the number of replicas, and the cost grows with system size. Report the replica count, the temperature or lambda ladder, the exchange interval and the acceptance ratios.']::text[], true, 100),
  ('steered-md', 'Steered MD', array['SMD', 'Steered molecular dynamics', 'Pulling simulation', 'Constant velocity pulling', 'Force probe']::text[], 'A force or moving restraint pulls part of the system, for example to unbind a ligand.', array['Steered MD applies an external force or a moving restraint to drag a group of atoms along a path, such as pulling a ligand out of its pocket or unfolding a domain. It gives insight into unbinding routes and the strength of the interactions along them.', 'Pulling is a non-equilibrium process, so single runs are noisy. Repeat them many times and, if you want free energies, combine them with the Jarzynski equality or use the snapshots to start umbrella sampling. Report the pulling rate and spring constant.']::text[], true, 110),
  ('free-energy-perturbation', 'Free energy perturbation (FEP)', array['FEP', 'Alchemical', 'Alchemical free energy', 'Relative binding free energy', 'RBFE', 'Absolute binding free energy', 'Thermodynamic integration']::text[], 'Alchemical calculations of binding or solvation free energies through intermediate states.', array['Free energy perturbation transforms one molecule into another, or switches a ligand on and off, through a series of lambda windows. Relative calculations rank related ligands, while absolute calculations estimate the binding free energy of a single ligand.', 'Each window is a separate simulation, and the results are combined with BAR or MBAR. Check the overlap between windows, convergence and the thermodynamic cycle, and report the soft-core settings, the lambda schedule and the estimated error.']::text[], true, 120),
  ('coarse-grained', 'Coarse-grained', array['CG', 'Martini', 'Coarse grained simulation', 'Coarse-grained MD']::text[], 'Simulations with groups of atoms represented as single beads, for longer time and length scales.', array['Coarse-grained models, such as Martini, replace several heavy atoms by one bead. Fewer particles and a smoother energy surface allow much larger systems and longer times, for example membrane remodelling or protein assembly.', 'The price is detail: hydrogen bonds and specific interactions are not described explicitly, and secondary structure is usually imposed. Report the model and its version, and consider backmapping to all-atom for analyses that need atomic detail.']::text[], false, 130),
  ('other', 'Other simulation types', array['Other', 'Custom simulation', 'Other method']::text[], 'Simulation systems and methods that are not in the standard list.', array['Molecular dynamics covers many systems and methods: QM/MM, constant-pH, polymers, materials, ions in solution and more. Records here describe the system and method in their methodology field and use tags for discovery.', 'If you think a system or method deserves its own category, you will be able to request it from your dashboard and the administrators will review it.']::text[], false, 140)
insert into public.blog_categories (slug, name, description, sort_order) values
  ('research', 'Research', 'Findings and case studies from simulation projects.', 10),
  ('methods', 'Methods', 'How to set up, run and analyse molecular dynamics simulations.', 20),
  ('tools-software', 'Tools and software', 'GROMACS, force fields, plotting and analysis tools.', 30),
  ('tutorials', 'Tutorials', 'Step-by-step guides written by the community.', 40),
  ('news', 'News', 'Platform updates and announcements.', 50)
